def valid_date(date):
    """
    Validate a date string in the format mm-dd-yyyy.

    Returns True if the date is valid according to the given rules,
    otherwise returns False.
    """
    if not isinstance(date, str):
        return False

    parts = date.split('-')

    if len(parts) != 3:
        return False

    month_str, day_str, year_str = parts

    if len(month_str) != 2 or len(day_str) != 2 or len(year_str) != 4:
        return False

    if not all(ch in "0123456789" for ch in month_str + day_str + year_str):
        return False

    month = int(month_str)
    day = int(day_str)

    if month < 1 or month > 12:
        return False

    if month in (1, 3, 5, 7, 8, 10, 12):
        if day < 1 or day > 31:
            return False
    elif month in (4, 6, 9, 11):
        if day < 1 or day > 30:
            return False
    else:
        if day < 1 or day > 29:
            return False

    return True
