def is_multiply_prime(a):
    """Return True if a is the product of exactly three prime numbers, otherwise False."""
    if a <= 1:
        return False

    prime_factors = 0
    n = a

    d = 2
    while d * d <= n:
        while n % d == 0:
            prime_factors += 1
            n //= d
            if prime_factors > 3:
                return False
        d += 1

    if n > 1:
        prime_factors += 1

    return prime_factors == 3
```

